'use strict';
// Minimal stand-in for the parts of the VS Code API this extension uses.
// It records what the extension registers so tests can assert on it.

const registered = new Map();
const config = {};
const messages = [];
const panels = [];

class EventEmitter {
  constructor() { this._l = []; this.event = l => { this._l.push(l); return { dispose() {} }; }; this.fired = []; }
  fire(v) { this.fired.push(v); this._l.forEach(l => l(v)); }
  dispose() {}
}

class RelativePattern { constructor(base, pattern) { this.base = base; this.pattern = pattern; } }
const watchers = [];
function fileWatcher(pattern) {
  const l = { change: [], create: [], delete: [] };
  const w = { pattern, onDidChange: f => l.change.push(f), onDidCreate: f => l.create.push(f), onDidDelete: f => l.delete.push(f),
    _fire: kind => l[kind].forEach(f => f()), disposed: false, dispose() { this.disposed = true; } };
  watchers.push(w);
  return w;
}

const Uri = {
  file: p => ({ fsPath: p, path: p, toString: () => 'file://' + p }),
  joinPath: (u, ...parts) => Uri.file([u.fsPath].concat(parts).join('/'))
};

function webviewPanel(viewType, title) {
  const listeners = [];
  const disposeL = [];
  const p = {
    viewType, title, revealed: 0, posted: [],
    webview: {
      html: '', cspSource: 'vscode-resource:',
      asWebviewUri: u => ({ toString: () => 'vscode-resource:' + u.fsPath }),
      postMessage: m => { p.posted.push(m); return Promise.resolve(true); },
      onDidReceiveMessage: l => { listeners.push(l); return { dispose() {} }; }
    },
    reveal() { p.revealed++; },
    onDidDispose: l => { disposeL.push(l); return { dispose() {} }; },
    dispose() { disposeL.forEach(l => l()); },
    _send(m) { listeners.forEach(l => l(m)); }
  };
  panels.push(p);
  return p;
}

const statusItems = [];
module.exports = {
  EventEmitter, Uri, RelativePattern,
  ViewColumn: { Active: -1, One: 1 },
  StatusBarAlignment: { Left: 1, Right: 2 },
  window: {
    activeTextEditor: undefined,
    state: { focused: true },
    onDidChangeWindowState: l => { module.exports.__windowListeners.push(l); return { dispose() {} }; },
    createOutputChannel: () => { const o = { lines: [], appendLine(l) { o.lines.push(l); }, show() {}, dispose() {} }; module.exports.__out = o; return o; },
    createStatusBarItem: () => { const i = { text: '', tooltip: '', command: '', shown: false, show() { i.shown = true; }, dispose() {} }; statusItems.push(i); return i; },
    createWebviewPanel: webviewPanel,
    showErrorMessage: m => { messages.push(['error', m]); return Promise.resolve(); },
    showInformationMessage: m => { messages.push(['info', m]); return Promise.resolve(); },
    showInputBox: async () => module.exports.__nextInput
  },
  commands: {
    registerCommand: (id, fn) => { registered.set(id, fn); return { dispose() {} }; },
    executeCommand: (id, ...a) => registered.get(id)(...a)
  },
  workspace: {
    workspaceFolders: undefined,
    getConfiguration: section => ({ get: (k, d) => (section + '.' + k) in config ? config[section + '.' + k] : d }),
    onDidChangeConfiguration: () => ({ dispose() {} }),
    createFileSystemWatcher: fileWatcher,
    findFiles: async () => module.exports.__found || []
  },
  __registered: registered,
  __config: config,
  __messages: messages,
  __panels: panels,
  __watchers: watchers,
  __windowListeners: [],
  __statusItems: statusItems,
  __nextInput: undefined
};
